import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[][] die = new int[n][6];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < 6; j++) {
                in.nextToken();
                die[i][j] = (int) in.nval;
            }

        // Faces opostas: (A,F), (B,D), (C,E). A rotacao horizontal de cada dado e livre,
        // logo, fixada a face inferior (contato), a contribuicao de um dado para um lado
        // pode ser o maximo das 4 faces laterais (as 4 faces que nao sao contato).
        int[] dp = new int[7];
        Arrays.fill(dp, -1);

        // Primeiro dado (base da torre): qualquer face pode ficar para baixo.
        int[] opp = buildOpp(die[0]);
        for (int f = 1; f <= 6; f++) {
            int t = opp[f];
            int side = maxSide(die[0], f, t);
            if (side > dp[t]) dp[t] = side;
        }

        // Dados seguintes: a face inferior deve ser igual a face superior exposta do dado anterior.
        for (int i = 1; i < n; i++) {
            opp = buildOpp(die[i]);
            int[] nd = new int[7];
            Arrays.fill(nd, -1);
            for (int v = 1; v <= 6; v++) {
                if (dp[v] < 0) continue;
                int t = opp[v]; // topo do dado atual, se a face inferior vale v
                int side = maxSide(die[i], v, t);
                int cand = dp[v] + side;
                if (cand > nd[t]) nd[t] = cand;
            }
            dp = nd;
        }

        int ans = 0;
        for (int v = 1; v <= 6; v++) if (dp[v] > ans) ans = dp[v];
        System.out.println(ans);
    }

    static int[] buildOpp(int[] d) {
        int[] o = new int[7];
        o[d[0]] = d[5]; o[d[5]] = d[0]; // A <-> F
        o[d[1]] = d[3]; o[d[3]] = d[1]; // B <-> D
        o[d[2]] = d[4]; o[d[4]] = d[2]; // C <-> E
        return o;
    }

    static int maxSide(int[] d, int bottom, int top) {
        int m = 0;
        for (int i = 0; i < 6; i++) {
            int v = d[i];
            if (v != bottom && v != top && v > m) m = v;
        }
        return m;
    }
}
